<script setup lang="ts">
import {computed} from 'vue'
import {qualityText as qt} from '../shared/i18n'

import type {Task} from '../shared/types'
defineProps<{form:Task;readonly:boolean}>()
const periods=computed(()=>[{value:1,label:qt('minutes')},{value:2,label:qt('hours')},{value:3,label:qt('days')},{value:4,label:qt('weeks')},{value:5,label:qt('months')},{value:6,label:qt('quarters')},{value:7,label:qt('years')}])
const weekdays=computed(()=>[qt('monday'),qt('tuesday'),qt('wednesday'),qt('thursday'),qt('friday'),qt('saturday'),qt('sunday')].map((label,i)=>({value:i+1,label})))
</script>
<template><a-divider orientation="left">{{qt('workSchedule')}}</a-divider>
 <a-form-item v-if="form.taskLevel===1" :label="qt('taskType')"><a-radio-group v-model:value="form.taskType"><a-radio :value="1">{{qt('temporaryTask')}}</a-radio><a-radio :value="2">{{qt('recurringTask')}}</a-radio></a-radio-group></a-form-item>
 <template v-if="form.taskType===2"><a-form-item :label="qt('startTime')"><a-date-picker show-time :value="form.startTime" value-format="x" @change="(v:unknown)=>form.startTime=v?Number(v):undefined" /></a-form-item><a-form-item :label="qt('endTime')"><a-date-picker show-time :value="form.endTime" value-format="x" @change="(v:unknown)=>form.endTime=v?Number(v):undefined" /></a-form-item></template>
 <template v-if="form.taskLevel===1"><a-form-item :label="qt('firstGenerationTime')"><a-date-picker show-time :value="form.firstGenerateTime" value-format="x" @change="(v:unknown)=>form.firstGenerateTime=v?Number(v):undefined" /></a-form-item><a-form-item v-if="form.taskType===2" :label="qt('generationInterval')"><a-space><a-input-number v-model:value="form.intervalValue" :min="1" :precision="0" /><a-select v-model:value="form.intervalUnit" :options="periods" style="width:110px" /></a-space></a-form-item>
 <a-form-item :label="qt('deadlineType')"><a-radio-group :value="form.reportDeadlineValue?'dynamic':'fixed'" @change="(e:{target:{value:string}})=>{if(e.target.value==='dynamic'){form.reportDeadlineValue=1;form.reportDeadlineUnit='DAY'}else{form.reportDeadlineValue=undefined;form.reportDeadlineUnit=undefined}}"><a-radio value="fixed">{{qt('fixedDeadline')}}</a-radio><a-radio value="dynamic">{{qt('calculatedAfterGeneration')}}</a-radio></a-radio-group></a-form-item>
 <a-form-item v-if="form.reportDeadlineValue" :label="qt('dynamicSubmissionDeadline')"><a-space><a-input-number v-model:value="form.reportDeadlineValue" :min="1" :precision="0" /><a-select v-model:value="form.reportDeadlineUnit" :options="[{value:'HOUR',label:qt('hours')},{value:'DAY',label:qt('days')}]" style="width:100px" /></a-space></a-form-item><a-form-item v-else :label="qt('submissionDeadline')"><a-date-picker show-time :value="form.reportDeadline" value-format="x" @change="(v:unknown)=>form.reportDeadline=v?Number(v):undefined" /></a-form-item>
 </template>
 <template v-if="form.taskLevel===2&&form.scheduleRules"><a-form-item :label="qt('inspectionCycle')"><a-select v-model:value="form.inspectionFrequency" disabled :options="[{value:1,label:qt('daily')},{value:2,label:qt('weekly')},{value:3,label:qt('monthly')}]" /></a-form-item><a-form-item :label="qt('runsPerCycle')"><a-input-number v-model:value="form.operationFrequency" :min="1" :precision="0" /></a-form-item>
 <template v-if="form.inspectionFrequency===1"><a-form-item v-for="(_,i) in form.scheduleRules.dayTimes" :key="i" :label="qt('no')+(i+1)+qt('times')"><a-space><a-time-picker v-model:value="form.scheduleRules.dayTimes![i]" value-format="HH:mm" format="HH:mm" /><a-button v-if="!readonly" @click="form.scheduleRules.dayTimes!.splice(i,1)">{{qt('remove')}}</a-button></a-space></a-form-item><a-button v-if="!readonly" @click="form.scheduleRules.dayTimes!.push('09:00')">{{qt('addDailyWorkTime')}}</a-button></template>
 <template v-if="form.inspectionFrequency===2"><a-form-item v-for="(point,i) in form.scheduleRules.weekTimes" :key="i" :label="qt('no')+(i+1)+qt('times')"><a-space><a-select v-model:value="point.weekDay" :options="weekdays" style="width:120px" /><a-time-picker v-model:value="point.time" value-format="HH:mm" format="HH:mm" /><a-button v-if="!readonly" @click="form.scheduleRules.weekTimes!.splice(i,1)">{{qt('remove')}}</a-button></a-space></a-form-item><a-button v-if="!readonly" @click="form.scheduleRules.weekTimes!.push({weekDay:1,time:'09:00'})">{{qt('addWeeklyWorkTime')}}</a-button></template>
 <template v-if="form.inspectionFrequency===3"><a-form-item v-for="(_,i) in form.scheduleRules.monthDateTimes" :key="i" :label="qt('workDate')+(i+1)"><a-space><a-date-picker v-model:value="form.scheduleRules.monthDateTimes![i]" show-time format="YYYY-MM-DD HH:mm" value-format="YYYY-MM-DD HH:mm" /><a-button v-if="!readonly" @click="form.scheduleRules.monthDateTimes!.splice(i,1)">{{qt('remove')}}</a-button></a-space></a-form-item><a-button v-if="!readonly" @click="form.scheduleRules.monthDateTimes!.push('')">{{qt('addMonthlyWorkDate')}}</a-button></template>
 </template></template>
